import React from 'react'

const Add = () => {
    return (
        <div className="form">
            <h1>Add New Member</h1>
            <input type="text" placeholder="name">Name</input>
            <input type="radio" placeholder="membership">Membership</input>
            <input type="text" placeholder="age">Age</input>
        </div>
    )
}

export default Add
